#!/usr/bin/env node
/**
 * Fails the build when the Motion Director recipe sources are not what the app needs at runtime.
 *
 * The shot adapter fetches /motion-studio/sources/<Stem>.tsx.txt (and its .card.md) from the deployed site. They are
 * generated by scripts/gen-demo-sources.mjs during `prebuild` and are not committed, so a deploy that skips the
 * generator ships a site whose adapter silently falls back to the plain recipes. This runs right after the generator
 * and checks every recipe of the catalog has its source and shot card.
 */
import fs from 'node:fs'
import path from 'node:path'

const OUT = path.resolve('public/motion-studio/sources')
const fail = (msg) => {
  console.error(`verify-motion-sources: ${msg}`)
  process.exit(1)
}

if (!fs.existsSync(path.join(OUT, 'index.json'))) fail(`${OUT}/index.json is missing: run scripts/gen-demo-sources.mjs before the build`)
const index = JSON.parse(fs.readFileSync(path.join(OUT, 'index.json'), 'utf8'))

const catalog = fs.readFileSync(path.resolve('src/data/motionRecipeCatalog.ts'), 'utf8')
const stems = [...new Set([...catalog.matchAll(/componentName: '([A-Za-z0-9]+)'/g)].map((m) => m[1]))]
if (stems.length < 100) fail(`found only ${stems.length} recipes in the catalog: the catalog format changed, update this check`)

const noSource = stems.filter((s) => !index[s] || !fs.existsSync(path.join(OUT, `${s}.tsx.txt`)))
const noCard = stems.filter((s) => !noSource.includes(s) && !fs.existsSync(path.join(OUT, `${s}.card.md`)))
if (noSource.length) fail(`${noSource.length} catalog recipes have no published source: ${noSource.slice(0, 12).join(', ')}${noSource.length > 12 ? ', …' : ''}`)
if (noCard.length) fail(`${noCard.length} recipes have no shot card: ${noCard.slice(0, 12).join(', ')}`)
console.log(`verify-motion-sources: ok, ${stems.length} catalog recipes each have a source and a shot card`)
